import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.DkuLC1cV.js";const k=JSON.parse('{"title":"Workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"guides/workspaces.md","filePath":"guides/workspaces.md"}'),n={name:"guides/workspaces.md"};function o(r,e,p,c,l,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h1><p>A <strong>workspace</strong> is a self-contained folder that holds everything Muxit needs to run your lab: device connectors, automation scripts, dashboards, drivers, and configuration.</p><h2 id="what-s-inside-a-workspace" tabindex="-1">What&#39;s Inside a Workspace <a class="header-anchor" href="#what-s-inside-a-workspace" aria-label="Permalink to &quot;What&#39;s Inside a Workspace&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-workspace/</span></span>
<span class="line"><span>  config/         Server settings (server.json, ai-memory.json)</span></span>
<span class="line"><span>  connectors/     Device configurations (.js files)</span></span>
<span class="line"><span>  scripts/        Automation scripts (.js files)</span></span>
<span class="line"><span>  dashboards/     Dashboard layouts (.dashboard.json)</span></span>
<span class="line"><span>  agents/         AI agent configs (.agent.json)</span></span>
<span class="line"><span>  drivers/</span></span>
<span class="line"><span>    community/    Free extension drivers (.dll)</span></span>
<span class="line"><span>    premium/      Licensed drivers (.dll)</span></span>
<span class="line"><span>  data/           Sandboxed file storage</span></span></code></pre></div><h2 id="first-run-setup" tabindex="-1">First-Run Setup <a class="header-anchor" href="#first-run-setup" aria-label="Permalink to &quot;First-Run Setup&quot;">​</a></h2><p>When you start Muxit for the first time, you&#39;ll see a setup screen with two options:</p><ol><li><strong>Create New Workspace</strong> --- Pick a location and name for your workspace. Muxit creates the folder structure automatically.</li><li><strong>Open Existing Workspace</strong> --- Point Muxit at an existing workspace directory.</li></ol><p>After setup, Muxit restarts and opens your workspace.</p><h2 id="creating-a-new-workspace" tabindex="-1">Creating a New Workspace <a class="header-anchor" href="#creating-a-new-workspace" aria-label="Permalink to &quot;Creating a New Workspace&quot;">​</a></h2><p>From the File menu, select <strong>New Workspace...</strong>. This opens a dialog where you can specify:</p><ul><li><strong>Location</strong> --- The filesystem path where the workspace will be created (e.g., <code>/home/user/my-lab</code> or <code>C:\\Users\\me\\Documents\\my-lab</code>).</li><li><strong>Name</strong> (optional) --- A friendly name for the workspace. Defaults to the folder name.</li></ul><p>Muxit creates the standard directory structure and a minimal <code>server.json</code> configuration file.</p><h2 id="opening-an-existing-workspace" tabindex="-1">Opening an Existing Workspace <a class="header-anchor" href="#opening-an-existing-workspace" aria-label="Permalink to &quot;Opening an Existing Workspace&quot;">​</a></h2><p>From the File menu, select <strong>Open Workspace...</strong>. The dialog shows:</p><ul><li>A list of all previously opened workspaces, sorted by last-opened time</li><li>The currently active workspace (highlighted with a &quot;current&quot; badge)</li><li>An option to create a new workspace</li></ul><p>Click any workspace in the list to switch to it. Muxit will restart automatically with the selected workspace.</p><h2 id="switching-workspaces" tabindex="-1">Switching Workspaces <a class="header-anchor" href="#switching-workspaces" aria-label="Permalink to &quot;Switching Workspaces&quot;">​</a></h2><p>When you switch workspaces, the server performs a graceful restart:</p><ol><li>All running scripts and agents are stopped</li><li>All connector connections are closed</li><li>The server shuts down</li><li>The launcher restarts the server with the new workspace path</li></ol><p>This process takes a few seconds. The browser will automatically reconnect when the server is back up.</p><h2 id="managing-the-workspace-list" tabindex="-1">Managing the Workspace List <a class="header-anchor" href="#managing-the-workspace-list" aria-label="Permalink to &quot;Managing the Workspace List&quot;">​</a></h2><ul><li>Workspaces are automatically added to the list when you create or open them</li><li>Click the <strong>X</strong> button on any workspace entry to remove it from the list (this does <strong>not</strong> delete the workspace folder)</li><li>Missing workspaces (deleted folders) are shown as dimmed with a &quot;missing&quot; badge</li></ul><h2 id="eula-acknowledgement-sandbox-mode" tabindex="-1">EULA Acknowledgement &amp; Sandbox Mode <a class="header-anchor" href="#eula-acknowledgement-sandbox-mode" aria-label="Permalink to &quot;EULA Acknowledgement &amp; Sandbox Mode&quot;">​</a></h2><p>Every Muxit workspace must have an accepted workspace acknowledgement before the server will let any driver perform a hardware <strong>write</strong> (setting a property, calling an action, or running a script). Until the acknowledgement is accepted the workspace loads in <strong>Sandbox mode</strong>: reads and polling continue, but every write is refused with error code <code>EULA_NOT_ACCEPTED</code>.</p><h3 id="what-gets-stored" tabindex="-1">What gets stored <a class="header-anchor" href="#what-gets-stored" aria-label="Permalink to &quot;What gets stored&quot;">​</a></h3><p>Acceptance produces two files inside the workspace:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-workspace/</span></span>
<span class="line"><span>  .muxit/</span></span>
<span class="line"><span>    EULA-ACCEPTED.md     # Human-readable acknowledgement + signed footer</span></span>
<span class="line"><span>    eula-history.jsonl   # Append-only audit trail of accept events</span></span>
<span class="line"><span>    workspace.json       # Stable workspace ID used in the footer</span></span></code></pre></div><p>The accepted file is a full copy of the current canonical EULA followed by a footer that identifies <em>who</em> accepted <em>which</em> version, <em>when</em>, for <em>which</em> workspace, and the SHA256 hash of the canonical body text.</p><h3 id="accepting-via-the-ui" tabindex="-1">Accepting via the UI <a class="header-anchor" href="#accepting-via-the-ui" aria-label="Permalink to &quot;Accepting via the UI&quot;">​</a></h3><p>When the server reports Sandbox mode the web UI replaces the main view with a blocking modal that shows the EULA text, asks for an identifier (name or email), and requires a checkbox before the <strong>Accept</strong> button is enabled. On accept the server writes <code>.muxit/EULA-ACCEPTED.md</code> atomically, appends a history entry, and unlocks the workspace.</p><h3 id="accepting-from-the-command-line" tabindex="-1">Accepting from the command line <a class="header-anchor" href="#accepting-from-the-command-line" aria-label="Permalink to &quot;Accepting from the command line&quot;">​</a></h3><p>Headless installs (<code>--cli</code> / <code>--mcp</code> modes, CI pipelines) accept the EULA one of two ways:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Explicit subcommand — writes the acceptance file and exits</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accept</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Jane Doe&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # prints the canonical text</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or set environment variables before launching the server</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MUXIT_EULA_ACCEPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MUXIT_EULA_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ci-bot&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span></code></pre></div><p>The env-var flow is logged with <code>action: &quot;accepted_ci&quot;</code> in the history file so CI-initiated acceptances are distinguishable from human ones.</p><h3 id="when-re-acceptance-is-required" tabindex="-1">When re-acceptance is required <a class="header-anchor" href="#when-re-acceptance-is-required" aria-label="Permalink to &quot;When re-acceptance is required&quot;">​</a></h3><p>The server treats EULA versions as semver (<code>1.0.0</code>, <code>1.1.0</code>, <code>2.0.0</code>):</p><ul><li><strong>Patch bump</strong> (<code>1.0.0</code> → <code>1.0.1</code>) — formatting / typo fix only, prior acceptance remains valid.</li><li><strong>Minor / major bump</strong> — requires re-acceptance; the modal shows the new version and notes the previous accepted version in the history.</li></ul><p>Re-acceptance is also required if the accepted file is edited outside Muxit (hash mismatch → <code>EulaTampered</code>) or if only the footer is present (<code>EulaCorrupt</code>).</p><h3 id="shared-workspaces-git" tabindex="-1">Shared workspaces (Git) <a class="header-anchor" href="#shared-workspaces-git" aria-label="Permalink to &quot;Shared workspaces (Git)&quot;">​</a></h3><p>The <code>.muxit/</code> folder commits with the workspace, so a team-shared Git repository carries the accepted EULA with it. The hash check still runs per user so any tampering is detected.</p><h2 id="workspace-catalog" tabindex="-1">Workspace Catalog <a class="header-anchor" href="#workspace-catalog" aria-label="Permalink to &quot;Workspace Catalog&quot;">​</a></h2><p>Muxit stores the list of known workspaces in a catalog file outside any workspace: <code>%LOCALAPPDATA%\\Muxit\\workspaces.json</code>. This file persists across workspace switches and server restarts.</p><h2 id="command-line-usage" tabindex="-1">Command-Line Usage <a class="header-anchor" href="#command-line-usage" aria-label="Permalink to &quot;Command-Line Usage&quot;">​</a></h2><p>You can also specify a workspace directly when starting the server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=/path/to/my-workspace</span></span></code></pre></div><p>Or with the compiled binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=/path/to/my-workspace</span></span></code></pre></div><p>The specified workspace is automatically registered in the catalog.</p>`,48)])])}const u=a(n,[["render",o]]);export{k as __pageData,u as default};
